import React, { useState, useEffect } from 'react';
import AspectRatio from "@mui/joy/AspectRatio";
import Card from "@mui/joy/Card";
import CardContent from "@mui/joy/CardContent";
import CardOverflow from "@mui/joy/CardOverflow";
import Divider from "@mui/joy/Divider";
import Typography from "@mui/joy/Typography";
import IconButton from "@mui/joy/IconButton";
import Link from "@mui/joy/Link";
import Favorite from "@mui/icons-material/Favorite";
import TextField from '@mui/material/TextField';
import MenuItem from '@mui/material/MenuItem';
import ResponsiveAppBar from '../inc/ResponsiveAppBar';
import 'bootstrap/dist/css/bootstrap.min.css';
import FooterApp from '../inc/FooterApp';

const BBCNews = () => {
  const [bbcNews, setBbcNews] = useState([]);
  const [keyword, setKeyword] = useState('');
  const [category, setCategory] = useState('');
  const [date, setDate] = useState('');
  const [source, setSource] = useState('');
  const [filteredNews, setFilteredNews] = useState([]);

  const getNews = () => {
    fetch(
      "https://newsapi.org/v2/top-headlines?country=us&category=business&apiKey=d2f986e7e87a48d3adcc1a5d23e146ee"
    )
      .then(res => res.json())
      .then((json) => {
        setBbcNews(json.articles);
        console.log(json.articles);
        setFilteredNews(json.articles);
      });
  };

  useEffect(() => {
    getNews();
  }, []);

  useEffect(() => {
    filterNews();
  }, [keyword, category, date, source]);

  const filterNews = () => {
    let filtered = bbcNews;

    if (keyword) {
      filtered = filtered.filter(news =>
        news.title.toLowerCase().includes(keyword.toLowerCase())
      );
    }

    if (category) {
      filtered = filtered.filter(news =>
        news.category?.toLowerCase() === category.toLowerCase()
      );
    }

    if (date) {
      filtered = filtered.filter(news => {
        const publishedDate = new Date(news.publishedAt);
        const filterDate = new Date(date);
        return publishedDate >= filterDate;
      });
    }

    if (source) {
      filtered = filtered.filter(news =>
        news.source.name.toLowerCase().includes(source.toLowerCase())
      );
    }

    setFilteredNews(filtered);
  };

  return (
    <>
      <ResponsiveAppBar />
      <div className="container">
        <div className="row my-4">
          <div className="col-md-12" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap' }}>
            <Typography level="h2" component="h2" gutterBottom>
              BBC News
            </Typography>
            <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap', alignItems: 'center', justifyContent: 'flex-end', flex: 1 }}>
              <TextField
                label="Search by keyword"
                variant="outlined"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                style={{ width: '200px' }}
              />
              <TextField
                label="Category"
                variant="outlined"
                select
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                style={{ width: '150px' }}
              >
                <MenuItem value="">All</MenuItem>
                <MenuItem value="world">World</MenuItem>
                <MenuItem value="politics">Politics</MenuItem>
                <MenuItem value="business">Business</MenuItem>
                <MenuItem value="technology">Technology</MenuItem>
                <MenuItem value="sports">Sports</MenuItem>
                {/* Add more categories as needed */}
              </TextField>
              <TextField
                label="Date"
                type="date"
                variant="outlined"
                value={date}
                onChange={(e) => setDate(e.target.value)}
                style={{ width: '150px' }}
                InputLabelProps={{
                  shrink: true,
                }}
              />
              <TextField
                label="Source"
                variant="outlined"
                value={source}
                onChange={(e) => setSource(e.target.value)}
                style={{ width: '150px' }}
              />
            </div>
          </div>
        </div>
        <div className="row" style={{ minHeight: '400px' }}>
          {filteredNews.length > 0 ? (
            filteredNews.map((news, index) => (
              <div key={index} className="col-md-4 mb-4">
                <Card variant="outlined" sx={{ width: '100%' }}>
                  <CardOverflow>
                    <AspectRatio ratio="2">
                      <img
                        src={news.urlToImage || 'https://images.unsplash.com/photo-1532614338840-ab30cf10ed36?auto=format&fit=crop&w=318&dpr=2 2x'}
                        loading="lazy"
                        alt={news.title}
                        style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                      />
                    </AspectRatio>
                    <IconButton
                      aria-label="Like minimal photography"
                      size="md"
                      variant="solid"
                      color="danger"
                      sx={{
                        position: "absolute",
                        zIndex: 2,
                        borderRadius: "50%",
                        right: "1rem",
                        bottom: 0,
                        transform: "translateY(50%)",
                      }}
                    >
                      <Favorite />
                    </IconButton>
                  </CardOverflow>
                  <CardContent>
                    <Typography level="title-md" sx={{ fontWeight: 800 }}>
                      <Link href={news.url} target="_blank" underline="none">
                        {news.title}
                      </Link>
                    </Typography>
                    <Typography level="body-sm">
                      {news.description || "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam..."}
                    </Typography>
                  </CardContent>
                  <CardOverflow variant="soft">
                    <Divider inset="context" />
                    <CardContent orientation="horizontal">
                      <Typography level="body-xs">6.3k views</Typography>
                      <Divider orientation="vertical" />
                      <Typography level="body-xs">1 hour ago</Typography>
                    </CardContent>
                  </CardOverflow>
                </Card>
              </div>
            ))
          ) : (
            <div className="col-md-12">
              <Typography level="body-md" component="p" align="center">
                No news articles available. Please try adjusting your filters or come back later.
              </Typography>
            </div>
          )}
        </div>
      </div>
      <FooterApp />
    </>
  );
};

export default BBCNews;
