import React, { useEffect, useState } from 'react';
import FooterApp from '../inc/FooterApp'
import ResponsiveAppBar from '../inc/ResponsiveAppBar'

const Documentation = () => {
    const [activeSection, setActiveSection] = useState('');

    useEffect(() => {
        const handleScroll = () => {
            const sections = document.querySelectorAll("section");
            let currentSection = '';
            sections.forEach(section => {
                const sectionTop = section.offsetTop;
                if (window.scrollY >= sectionTop - 100) {
                    currentSection = section.getAttribute('id');
                }
            });
            setActiveSection(currentSection);

            const sidebar = document.querySelector('.Documentation-sidebar');
            const footer = document.querySelector('footer');
            const footerTop = footer.getBoundingClientRect().top;
            const windowHeight = window.innerHeight;

            if (footerTop < windowHeight) {
                sidebar.style.maxHeight = `${footerTop - 80}px`; // 80px is the top margin of the sidebar
            } else {
                sidebar.style.maxHeight = `calc(100vh - 80px)`;
            }
        };

        window.addEventListener('scroll', handleScroll);
        return () => {
            window.removeEventListener('scroll', handleScroll);
        };
    }, []);

    return (
        <>
            <ResponsiveAppBar />
            <div className="Documentation">
                <nav className="Documentation-sidebar">
                    <ul>
                        <li className={activeSection === 'introduction' ? 'active' : ''}><a href="#introduction">Introduction</a></li>
                        <li className={activeSection === 'technologies' ? 'active' : ''}><a href="#technologies">Technologies Used</a></li>
                        <li className={activeSection === 'setup' ? 'active' : ''}><a href="#setup">Setup Instructions</a></li>
                        <li className={activeSection === 'usage' ? 'active' : ''}><a href="#usage">Usage</a></li>
                        <li className={activeSection === 'api' ? 'active' : ''}><a href="#api">API Integration</a></li>
                        <li className={activeSection === 'docker' ? 'active' : ''}><a href="#docker">Docker Setup</a></li>
                        <li className={activeSection === 'contribute' ? 'active' : ''}><a href="#contribute">Contributing</a></li>
                        <li className={activeSection === 'license' ? 'active' : ''}><a href="#license">License</a></li>
                    </ul>
                </nav>
                <main className="Documentation-content">
                    <section id="introduction">
                        <h2>Introduction</h2>
                        <p>Welcome to the News Hub app documentation. This application aggregates news from various sources like BBC, NY Times, and The Guardian using React and Docker. It aims to provide a comprehensive platform for accessing the latest news articles.</p>
                    </section>
                    <section id="technologies">
                        <h2>Technologies Used</h2>
                        <ul>
                            <li>React JS: A JavaScript library for building user interfaces.</li>
                            <li>Material-UI: A popular React UI framework for building fast and beautiful UIs.</li>
                            <li>News API: An API service used to fetch news articles.</li>
                            <li>Docker: A platform to develop, ship, and run applications inside containers.</li>
                        </ul>
                    </section>
                    <section id="setup">
                        <h2>Setup Instructions</h2>
                        <p>To set up the project, follow these steps:</p>
                        <ol>
                            <li>Clone the repository: <code>git clone https://github.com/your-repo/news-hub.git</code></li>
                            <li>Navigate into the project directory: <code>cd news-hub</code></li>
                            <li>Install dependencies: <code>npm install</code></li>
                            <li>Start the development server: <code>npm start</code>. The app will be available at <code>http://localhost:3000</code>.</li>
                        </ol>
                    </section>
                    <section id="usage">
                        <h2>Usage</h2>
                        <p>To use the News Hub app, simply navigate through the various sections using the navigation bar. You can filter news articles by category, keyword, and other criteria. The app also allows you to favorite articles for easy access later.</p>
                    </section>
                    <section id="api">
                        <h2>API Integration</h2>
                        <p>The News Hub app integrates with the News API to fetch the latest news articles. You can extend this functionality by adding more APIs or custom data sources. The API key is required to authenticate requests and can be configured in the environment variables.</p>
                    </section>
                    <section id="docker">
                        <h2>Docker Setup</h2>
                        <p>The application can be containerized using Docker for consistent development and deployment environments. To build and run the Docker container:</p>
                        <ol>
                            <li>Build the Docker image: <code>docker build -t news-hub .</code></li>
                            <li>Run the Docker container: <code>docker run -p 3000:3000 news-hub</code></li>
                        </ol>
                    </section>
                    <section id="contribute">
                        <h2>Contributing</h2>
                        <p>We welcome contributions from the community. Please read the contributing guidelines in the repository. You can open issues for bugs or feature requests, and submit pull requests for improvements.</p>
                    </section>
                    <section id="license">
                        <h2>License</h2>
                        <p>This project is licensed under the MIT License. Feel free to use, modify, and distribute this software as per the terms of the license.</p>
                    </section>
                </main>
            </div>
            <FooterApp />
        </>
    )
}

export default Documentation