import React, { useState, useEffect } from 'react';
import ResponsiveAppBar from "../inc/ResponsiveAppBar";
import Carousel from "react-material-ui-carousel";
import Link from "@mui/joy/Link";
import { Paper, Button } from "@mui/material";
import ChevronLeftIcon from "@mui/icons-material/ChevronLeft";
import ChevronRightIcon from "@mui/icons-material/ChevronRight";
import FooterApp from '../inc/FooterApp';

const Home = () => {
  const [nytNews, setnytNews] = useState([]);

  const getNews = () => {
    fetch(
      "https://api.nytimes.com/svc/topstories/v2/home.json?api-key=7q1k6TWUL9CpVipJmC0MnXGceZzYTnma"
    )
      .then(res => res.json())
      .then((json) => {
        setnytNews(json.results);
      });
  };

  useEffect(() => {
    getNews();
  }, []);

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <ResponsiveAppBar />
      <div style={{minHeight: '500px'}}>
        <Carousel
          navButtonsProps={{
            style: {
              color: "grey",
              backgroundColor: "white",
              borderRadius: 50,
            },
          }}
          navButtonsWrapperProps={{
            style: {
              bottom: "0",
              top: "unset",
            },
          }}
          NextIcon={<ChevronRightIcon />}
          PrevIcon={<ChevronLeftIcon />}
          navButtonsAlwaysVisible={true}
        >
          {nytNews.slice(0, 5).map((news, index) => (
            <Paper key={index} style={{ position: 'relative', }}>
              <img
                src={news.multimedia[0]?.url || 'https://via.placeholder.com/320x180'}
                loading="lazy"
                alt={news.title}
                style={{ width: '100%', height: '500px', objectFit: 'cover', objectPosition: 'center' }}
              />
              <Link href={news.url} target="_blank" underline="none" style={{ display: 'block', color: 'black', fontWeight: '800', textAlign: 'center', margin: '10px 0' }}>
                {news.title}
              </Link>
            </Paper>
          ))}
        </Carousel>
      </div>
      <FooterApp />
    </div>
  );
};

export default Home;
